import numpy as np
from openai import OpenAI


def similarity_score(embedding1, embedding2, config=None):
    config = config or {}
    with OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY']) as client:
        cosine_similarity = np.dot(embedding1, embedding2) / (np.linalg.norm(embedding1) * np.linalg.norm(embedding2))
    return {'similarity_score': cosine_similarity}

import os
from openai import OpenAI


def embed_for_search(query, documents, config=None):
    config = config or {}
    with OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY']) as client:
        query_embedding = client.embeddings.create(model='text-embedding-3-small', input=query['text']).data[0].embedding
        document_embeddings = client.embeddings.create(model='text-embedding-3-small', input=[document['text'] for document in documents]).data
    return {'query_embedding': query_embedding, 'document_embeddings': [embedding.embedding for embedding in document_embeddings]}

import os
from openai import OpenAI


def get_client(config=None):
    config = config or {}
    return OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY'])

from typing import List, Dict


def normalize_payload(payloads: List[Dict]) -> List[Dict]:
    return [{'text': payload['text']} for payload in payloads]


def normalize_response(response) -> List[Dict]:
    return [{'embedding': embedding.embedding} for embedding in response.data]

import os
from openai import OpenAI


def summarize_embedding_job_results(job_results, config=None):
    config = config or {}
    with OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY']) as client:
        response = client.completions.create(
            model='text-davinci-003',
            prompt=f'Summarize the following embedding job results: {job_results}',
            max_tokens=100
        )
    return {'summary': response.choices[0].text.strip()}

